class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        m, n = len(grid), len(grid[0])
        for i in range(m):
            # Sort the elements on the main diagonal from left to right
            grid[i][i:] = sorted(grid[i][i:])
            # Sort the elements on the anti-diagonal from right to left
            if i < m - 1:
                grid[i][:-i-1] = sorted(grid[i][:-i-1], reverse=True)

        return grid

