class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        rows = len(grid)
        cols = len(grid[0])

        # Create a list to store the elements of each diagonal
        diagonals = []

        # Collect elements from all diagonals
        for i in range(rows):
            for j in range(cols):
                if i + j >= rows:
                    diagonals.append((i + j - rows, j))
                else:
                    diagonals.append((i, j))

        # Sort each diagonal
        for i in range(len(diagonals)):
            diagonals[i] = sorted(diagonals[i], reverse=True)

        # Reconstruct the grid using sorted diagonals
        result = [[0] * cols for _ in range(rows)]
        for i in range(rows):
            for j in range(cols):
                result[i][j] = diagonals[(i + j) % len(diagonals)][0]
                diagonals[(i + j) % len(diagonals)].pop(0)

        return result

