class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        m, n = len(grid), len(grid[0])
        pq = []

        # Push all elements from the first row into the priority queue
        for j in range(n):
            hq.heappush(pq, (grid[0][j], 0, j))

        # Process each diagonal
        for i in range(1, m):
            for j in range(i+1):
                value, r, c = hq.heappop(pq)

                # Add the current element to the result matrix
                grid[r][c] = value

                # Push the next element into the priority queue
                if r + 1 < m:
                    hq.heappush(pq, (grid[r+1][c], r+1, c))
                if c + 1 < n:
                    hq.heappush(pq, (grid[r][c+1], r, c+1))

        return grid

