class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        heap = []
        for i in range(len(grid)):
            for j in range(len(grid)):
                heapq.heappush(heap, (i - j, grid[i][j]))

        res = [[0]*len(grid) for _ in range(len(grid))]
        i, j = 0, 0

        while heap:
            _, num = heapq.heappop(heap)
            res[i][j] = num
            if i + 1 < len(grid):
                i += 1
            else:
                j += 1

        return res

