class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        heap = []
        m, n = len(grid), len(grid[0])

        # Push all elements from the matrix into the heap
        for i in range(m):
            for j in range(n):
                heapq.heappush(heap, (i - j, grid[i][j]))

        # Reconstruct the matrix while sorting each diagonal
        result = [[0] * n for _ in range(m)]
        row, col = 0, 0

        while heap:
            di, val = heapq.heappop(heap)
            result[row][col] = val

            if di + 1 < m:
                row += 1
            else:
                col += 1

        return result

