class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        m, n = len(grid), len(grid[0])
        diagonals = collections.defaultdict(list)
        for i in range(m):
            for j in range(n):
                diagonals[i-j].append(grid[i][j])

        for key in diagonals.keys():
            diagonals[key].sort(reverse=True if key % 2 != 0 else False)

        for i in range(m):
            for j in range(n):
                grid[i][j] = diagonals[i - j].pop()

        return grid

