class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        diags = collections.defaultdict(list)
        for i in range(n):
            for j in range(n):
                diags[j - i].append(grid[i][j])

        for k in diags.keys():
            diags[k].sort(reverse=True if k < 0 else False)

        ans = [[0]*n for _ in range(n)]
        row, col = 0, 0
        for k in diags.keys():
            for val in diags[k]:
                ans[row][col] = val
                row += 1
                col += 1

        return ans

