class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        m, n = len(grid), len(grid[0])
        rows, cols = [], []

        # Collect elements from each diagonal
        for i in range(m):
            rows.append((i, i))
            cols.append((m - 1 - i, i))

        # Sort each diagonal
        for row in rows:
            hq.heapify(rows)
            for _ in range(n):
                grid[row[0]][row[1]] = hq.heappop(rows)[1]

        for col in cols:
            hq.heapify(cols)
            for _ in range(n):
                grid[col[0]][col[1]] = hq.heappop(cols)[1]

        return grid

