class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        m, n = len(grid), len(grid[0])
        res = [[0]*n for _ in range(m)]
        for i in range(m):
            for j in range(n):
                res[j-m+i][i] = grid[i][j]

        for i in range(m+n-1):
            cur = []
            for j in range(max(0,i-n+1), min(i,m)):
                cur.append(res[j][i-j])
            cur.sort(reverse=True)
            for j in range(max(0,i-n+1), min(i,m)):
                res[j][i-j] = cur.pop()

        for i in range(n):
            cur = []
            for j in range(min(i,n), max(0,i+m-1)):
                cur.append(res[i+j][i])
            cur.sort()
            for j in range(min(i,n), max(0,i+m-1)):
                res[i+j][i] = cur.pop()

        return res

