class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        for i in range(n):
            # Sort the submatrix along the current diagonal
            for j in range(i + 1, n):
                if grid[j][i] > grid[i][j]:
                    grid[i][j], grid[j][i] = grid[j][i], grid[i][j]

        for i in range(1, n):
            # Sort the submatrix along the current diagonal
            for j in range(i - 1, -1, -1):
                if grid[j][i] < grid[i][j]:
                    grid[i][j], grid[j][i] = grid[j][i], grid[i][j]

        return grid

