class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        rows, cols = len(grid), len(grid[0])
        result = [[0] * cols for _ in range(rows)]
        diags = collections.defaultdict(list)

        # Collect elements into their respective diagonals
        for i in range(rows):
            for j in range(cols):
                diags[i - j].append(grid[i][j])

        # Sort each diagonal in non-increasing or non-decreasing order
        for key in diags:
            if key >= 0:
                diags[key].sort(reverse=True)
            else:
                diags[key].sort()

        # Fill the result matrix with sorted diagonals
        k = 0
        for i in range(rows):
            for j in range(cols):
                result[i][j] = diags[k].pop(0)
                k += 1

        return result

