class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        # Create a heap for each diagonal
        diags = [[] for _ in range(2 * n - 1)]

        # Populate the heap for each diagonal
        for i in range(n):
            for j in range(n):
                heapq.heappush(diags[i + j], grid[i][j])

        # Reconstruct the matrix from the heaps
        for i in range(n):
            for j in range(n):
                grid[i][j] = heapq.heappop(diags[i + j])

        return grid

