class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        m, n = len(grid), len(grid[0])
        heap = []
        for i in range(m):
            for j in range(n):
                heapq.heappush(heap, (i - j, j, grid[i][j]))

        res = [[0] * n for _ in range(m)]
        i, j = 0, 0

        while heap:
            _, col, val = heapq.heappop(heap)
            res[i][col] = val

            if col + 1 < n:
                heapq.heappush(heap, (i - (col + 1), col + 1, grid[i][col + 1]))

            if i + 1 < m:
                heapq.heappush(heap, ((i + 1) - col, col, grid[i + 1][col]))

            i += 1

        return res

