class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        m, n = len(grid), len(grid[0])
        heap = []
        for i in range(m):
            for j in range(n):
                hq.heappush(heap, (i-j, grid[i][j]))

        ans = [[None] * n for _ in range(m)]
        for i in range(m):
            for j in range(n):
                di, dj = i - j, j
                while heap and heap[0][0] == di + dj:
                    d, v = hq.heappop(heap)
                    ans[i][j] = v
                    di += 1

        return ans

