class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        # Flatten the grid into a single list
        flat_list = [item for sublist in grid for item in sublist]
        # Use min heap to sort the flattened list
        min_heap = []
        for num in flat_list:
            heapq.heappush(min_heap, num)

        # Reconstruct the grid from the sorted list
        result = []
        for i in range(n):
            row = []
            for j in range(i + 1):
                if min_heap:
                    row.append(heapq.heappop(min_heap))
                else:
                    break
            result.append(row)

        return result

