class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        rows, cols = len(grid), len(grid[0])
        # Create a list to store elements along each diagonal
        diag_elements = []

        # Collect elements along each diagonal
        for i in range(rows):
            for j in range(cols):
                if i - j < 0:
                    diag_elements.append((i + j, grid[i][j]))
                else:
                    diag_elements.append((i - j + rows - 1, grid[i][j]))

        # Sort elements along each diagonal
        diag_elements.sort(key=lambda x: (-x[0], x[1]))

        # Place sorted elements back into the grid
        for i in range(rows):
            for j in range(cols):
                if i - j < 0:
                    grid[i][j] = diag_elements.pop(0)[1]
                else:
                    grid[i][j] = diag_elements.pop(0)[1]

        return grid

def find_subgrid(S, T):
    N, M = len(S), len(T)

    for a in range(N - M + 1):
        for b in range(N - M + 1):
            if all(S[a+i-1][b+j-1] == T[i][j] for i in range(M) for j in range(M)):
                return a + 1, b + 1

    raise ValueError("No matching subgrid found")

