class Solution:
    def separateSquares(self, squares: List[List[int]]) -> float:
        # Sort squares by their leftmost x-coordinates
        squares.sort(key=lambda x: x[0])

        # Dictionary to store cumulative area for each x-coordinate
        cum_area = collections.defaultdict(float)
