        for x, y, l in squares:
            # Add the area of the current square
            cum_area[x + l] += l ** 2

            # Subtract the area of the previous square if any
            if x > 0:
                cum_area[x - 1] -= l ** 2

        # Find the y-coordinate where the total area above and below is equal
        for y in range(len(cum_area)):
            if cum_area[y] == cum_area[len(cum_area) - 1 - y]:
                return y / len(squares)

        # If no such y-coordinate is found, return 0 (though this case should not happen based on constraints)
        return 0

