class Solution:
    def separateSquares(self, squares: List[List[int]]) -> float:
        # Sort the squares by their rightmost x-coordinate
        squares.sort(key=lambda x: x[0] + x[2])

        # Initialize variables
        left, right, total_area_above, total_area_below = 0, len(squares), 0, 0

        while left < right:
            # Calculate the current square
            x, y, l = squares[left]

            # Update the total area above the line
            if x + l > squares[right][0]:
                total_area_above += l * (squares[right][1] - y)

            # Move the right pointer to the next square or end of the list
            while right < len(squares) and squares[right][0] <= x + l:
                right += 1

            # Calculate the current square
            x, y, l = squares[right - 1]

            # Update the total area below the line
            if x < squares[left][0]:
                total_area_below += l * (y - squares[left][1])

            # Move the left pointer to the next square or start of the list
            while left >= 0 and squares[left][0] >= x - l:
                left -= 1

            # Check if the areas above and below the line are equal
            if total_area_above == total_area_below:
                return y / 10 ** 5
            elif total_area_above > total_area_below:
                right -= 1
            else:
                left += 1

        return 0.0

