class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Build adjacency list
        adj_list = [[] for _ in range(n)]
        for u, v, w in edges:
            adj_list[u].append((v, w))
            adj_list[v].append((u, w))

        # Initialize distance matrix
        dist = [[float('inf')] * n for _ in range(n)]
        for i in range(n):
            dist[i][i] = 0

        # Floyd-Warshall algorithm to find shortest paths
        for k in range(n):
            for i in range(n):
                for j in range(n):
                    if dist[i][k] + dist[k][j] < dist[i][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

        # Check if node 0 can be reached from all other nodes
        if any(dist[0][i] == float('inf') for i in range(1, n)):
            return -1

        # Function to check if removing edges can satisfy the condition
        def can_remove_edges(max_weight):
            visited = set()
            queue = [(0, 0)]
            while queue:
                current_node, current_weight = heapq.heappop(queue)
                if current_node == n - 1:
                    return True
                if current_node not in visited:
                    visited.add(current_node)
                    for neighbor, weight in adj_list[current_node]:
                        if weight <= max_weight:
                            heapq.heappush(queue, (neighbor, current_weight + weight))
            return False

        # Binary search to find the minimum possible maximum edge weight
        low, high = 0, 1e9
        while low < high:
            mid = (low + high + 1) // 2
            if can_remove_edges(mid):
                low = mid
            else:
                high = mid - 1

        return low if can_remove_edges(low) else -1

