                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            root_x = find(x)
            root_y = find(y)
            if root_x == root_y:
                return False
            if rank[root_x] > rank[root_y]:
                parent[root_y] = root_x
            elif rank[root_x] < rank[root_y]:
                parent[root_x] = root_y
            else:
                parent[root_y] = root_x
                rank[root_x] += 1
            return True

        mst_weight = 0
        for u, v, w in edges:
            if find(u) != find(v) and rank[find(u)] < rank[find(v)] + threshold:
                union(u, v)
                mst_weight += w

        return mst_weight

    def dfs(self, graph, node, visited):
        visited.add(node)
        for neighbor, weight in graph[node]:
            if neighbor not in visited:
                self.dfs(graph, neighbor, visited)

