        for i in range(n):
            if not visited[i]:
                dfs(i)
                component_count += 1

        # If there's only one component, it means we can't satisfy the condition
        if component_count == 1:
            return -1

        # Calculate the maximum edge weight for each component
        max_edge_weights = [0] * component_count
        for i in range(n):
            if not visited[i]:
                current_component_max_weight = 0
                dfs(i)
                for j in range(n):
                    if not visited[j] and adj_list[i][j][1] > threshold:
                        current_component_max_weight = max(current_component_max_weight, adj_list[i][j][1])
                max_edge_weights[component_count - 1] = max(max_edge_weights[component_count - 1], current_component_max_weight)

        # Find the minimum maximum edge weight across all components
        return min(max_edge_weights)

