            adj[u].append((v, w))
            adj[v].append((u, w))

        def dfs(node, parent):
            if seen[node]:
                return False
            seen[node] = True
            for neighbor, weight in adj[node]:
                if neighbor == parent:
                    continue
                if not dfs(neighbor, node):
                    return False
            return True

        # Group edges by their weights
        weight_to_edges = collections.defaultdict(list)
        for u, v, w in edges:
            weight_to_edges[w].append((u, v))

        def get_max_weight(node, parent, visited):
            if seen[node]:
                return 0
            seen[node] = True
            max_weight = 0
            for neighbor, weight in adj[node]:
                if neighbor == parent:
                    continue
                max_weight = max(max_weight, weight + get_max_weight(neighbor, node, visited))
            return max_weight

        min_max_weight = float('inf')
        for weight, edges in weight_to_edges.items():
            if weight >= threshold:
                continue
            seen = [False] * n
            for u, v in edges:
                if not dfs(u, None):
                    continue
                max_weight = get_max_weight(v, u, seen)
                min_max_weight = min(min_max_weight, max_weight)
                break
        return min_max_weight if min_max_weight != float('inf') else -1

