class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Create adjacency list representation of the graph
        adj_list = [[] for _ in range(n)]
        for u, v, w in edges:
            adj_list[u].append((v, w))
            adj_list[v].append((u, w))

        # Initialize distance array with infinity
        dist = [float('inf')] * n

        # Perform BFS starting from node 0
        def bfs(start):
            queue = [(0, start)]
            while queue:
                weight, node = heapq.heappop(queue)
                if weight > dist[node]:
                    continue
                dist[node] = weight
                for neighbor, weight in adj_list[node]:
                    if weight >= threshold and weight + weight > dist[neighbor]:
                        heapq.heappush(queue, (weight + weight, neighbor))

        # Run BFS from each node
        for i in range(n):
            bfs(i)

        # Find the maximum weight in the graph
        max_weight = max(dist)

        # Check if all nodes can be reached from node 0
        if max_weight == float('inf'):
            return -1

        return max_weight

