class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Build adjacency list representation of the graph
        adj_list = defaultdict(list)
        for u, v, w in edges:
            adj_list[u].append((v, w))
            adj_list[v].append((u, w))

        # Helper function to perform DFS to find connected components
        def dfs(node, parent):
            visited[node] = True
            for neighbor, weight in adj_list[node]:
                if not visited[neighbor] and neighbor != parent:
                    dfs(neighbor, node)

        # Perform DFS on each node to identify connected components
        visited = [False] * n
        components = []
        for i in range(n):
            if not visited[i]:
                component = set()
                dfs(i, -1)
                components.append(component)

        # Initialize the result variable to store the minimum maximum weight
        res = float('inf')

        # Iterate through each connected component
        for component in components:
            # Sort the edges in the component by weight
            component.sort(key=lambda x: x[1])

            # Check if removing edges from the component can satisfy the conditions
            for i in range(len(component)):
                for j in range(i + 1, len(component)):
                    if component[j][1] >= threshold:
                        break
                else:
                    # Calculate the maximum weight of the component after removing edges
                    max_weight = sum(weight for _, weight in component[:j+1])
                    res = min(res, max_weight)
                    break

        # Return the result if it was found, otherwise return -1
        return res if res != float('inf') else -1

