class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        if len(fruits) > len(baskets):
            return len(fruits) - len(baskets)

        l, r, total_fruit = 0, 0, 0
        basket_dict = {}

        while r < len(fruits):
            basket_dict[fruits[r]] = basket_dict.get(fruits[r], 0) + 1
            total_fruit += fruits[r]

            while len(basket_dict) > len(baskets):
                basket_dict[fruits[l]] -= 1
                if basket_dict[fruits[l]] == 0:
                    del basket_dict[fruits[l]]
                total_fruit -= fruits[l]
                l += 1

            r += 1

        return len(fruits) - total_fruit

