class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        if not fruits or not baskets:
            return 0

        # Dictionary to store the frequency of each fruit type
        fruit_freq = {}
        for fruit in fruits:
            fruit_freq[fruit] = fruit_freq.get(fruit, 0) + 1

        # Dictionary to store the number of baskets available for each fruit type
        basket_count = {fruit: min(baskets[i], fruit_freq[fruit]) for i, fruit in enumerate(fruits)}

        # Initialize variables to keep track of the current window size and the total number of fruits remaining
        window_size = 0
        total_fruits_remaining = sum(fruit_freq.values())

        # Iterate through the fruits from left to right
        for fruit in fruits:
            # Decrease the count of the current fruit in the window
            basket_count[fruit] -= 1

            # If the count of the current fruit becomes negative, move the left pointer until the count becomes non-negative
            while basket_count[fruit] < 0:
                basket_count[fruits[window_size]] += 1
                window_size += 1

            # Update the total number of fruits remaining
            total_fruits_remaining -= basket_count[fruit]

        # Return the number of fruits that remain unplaced
        return total_fruits_remaining

