class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        # Initialize pointers for the sliding window
        start, end = 0, 0
        # Dictionary to store the frequency of each fruit
        fruit_count = {}
        max_fruit_count = 0

        # Iterate through the array using the end pointer
        while end < len(fruits):
            # Update the count of the current fruit
            if fruits[end] in fruit_count:
                fruit_count[fruits[end]] += 1
            else:
                fruit_count[fruits[end]] = 1

            # Update the maximum fruit count in the window
            max_fruit_count = max(max_fruit_count, fruit_count[fruits[end]])

            # If the window size exceeds the capacity of the baskets, move the start pointer
            while end - start + 1 > len(baskets):
                fruit_count[fruits[start]] -= 1
                if fruit_count[fruits[start]] == 0:
                    del fruit_count[fruits[start]]
                start += 1

            # Calculate the number of fruits remaining unplaced
            unplaced_fruits = len(fruits) - (end - start + 1)
            # Ensure the number of fruits remaining unplaced does not exceed the maximum fruit count
            if unplaced_fruits > max_fruit_count:
                unplaced_fruits = max_fruit_count

            # Return the number of fruits remaining unplaced
            return unplaced_fruits

