class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        count_map = {}
        for fruit in fruits:
            if fruit not in count_map:
                count_map[fruit] = 0
            count_map[fruit] += 1

        # Sort the fruits based on their frequencies
        sorted_fruits = sorted(count_map.items(), key=lambda x: x[1], reverse=True)

        max_baskets = len(baskets)
        unplaced_count = 0

        for fruit, frequency in sorted_fruits:
            if frequency > max_baskets - unplaced_count:
                unplaced_count += frequency - (max_baskets - unplaced_count)

        return unplaced_count
